def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    n, m = int(input[ptr]), int(input[ptr+1])
    ptr += 2
    points = list(map(int, input[ptr:ptr+n]))
    ptr += n
    segments = []
    for _ in range(m):
        l, r = int(input[ptr]), int(input[ptr+1])
        segments.append((l, r))
        ptr += 2

    from itertools import product

    for colors in product([0, 1], repeat=n):
        valid = True
        for l, r in segments:
            red = 0
            blue = 0
            for i in range(n):
                if l <= points[i] <= r:
                    if colors[i] == 0:
                        red += 1
                    else:
                        blue += 1
            if abs(red - blue) > 1:
                valid = False
                break
        if valid:
            print(' '.join(map(str, colors)))
            return
    print(-1)

main()
